  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ================= ENUMS =================\n\nenum Role {\n  PEMILIK\n  KASIR\n}\n\nenum EmployeeStatus {\n  AKTIF\n  NONAKTIF\n}\n\nenum PaymentMethod {\n  CASH\n  QRIS\n  DEBIT\n  KREDIT\n  TRANSFER\n}\n\nenum OrderStatus {\n  PENDING\n  PAID\n  CANCELLED\n  REFUNDED\n}\n\n// ================= AUTH & USER =================\n\nmodel User {\n  id       String  @id @default(uuid())\n  email    String  @unique\n  password String\n  name     String\n  role     Role    @default(KASIR)\n  isActive Boolean @default(true)\n\n  emailVerifiedAt   DateTime?\n  passwordChangedAt DateTime?\n  employee          Employee?\n  orders            Order[]\n\n  verificationTokens  VerificationToken[]\n  passwordResetTokens PasswordResetToken[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Token untuk verifikasi email — expired otomatis, sekali pakai\nmodel VerificationToken {\n  id        String    @id @default(uuid())\n  token     String    @unique\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n}\n\n// Token untuk lupa password — terpisah dari verifikasi email, umur lebih pendek\nmodel PasswordResetToken {\n  id        String    @id @default(uuid())\n  token     String    @unique\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n}\n\n// ================= DATA KARYAWAN =================\n\nmodel Employee {\n  id     String @id @default(uuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  employeeCode String         @unique // NIP internal, mis. \"KRY-0001\"\n  phone        String         @unique\n  address      String?\n  birthDate    DateTime?\n  photo        String?\n  position     String? // jabatan, mis. \"Barista\", \"Kasir Shift Pagi\"\n  joinDate     DateTime       @default(now())\n  status       EmployeeStatus @default(AKTIF)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ================= PRODUK =================\n\nmodel Category {\n  id       Int       @id @default(autoincrement())\n  name     String    @unique\n  products Product[]\n}\n\nmodel Product {\n  id                Int                @id @default(autoincrement())\n  sku               String?            @unique\n  name              String\n  price             Decimal            @db.Decimal(10, 2)\n  discount          Decimal            @default(0) @db.Decimal(10, 2)\n  costPrice         Decimal?           @db.Decimal(10, 2)\n  stock             Int                @default(0)\n  image             String?\n  isActive          Boolean            @default(true)\n  categoryId        Int\n  category          Category           @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n  orderItems        OrderItem[]\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  orderRequestItems OrderRequestItem[]\n\n  @@index([categoryId])\n}\n\n// ================= TRANSAKSI =================\n\nmodel Order {\n  id            Int           @id @default(autoincrement())\n  customerName  String?\n  totalAmount   Decimal       @db.Decimal(10, 2)\n  discount      Decimal       @default(0) @db.Decimal(10, 2)\n  note          String?\n  paymentMethod PaymentMethod @default(CASH)\n  status        OrderStatus   @default(PAID)\n  cashierId     String\n  cashier       User          @relation(fields: [cashierId], references: [id], onDelete: Restrict)\n  orderItems    OrderItem[]\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  @@index([createdAt])\n  @@index([cashierId])\n  @@index([status])\n  @@index([status, createdAt])\n}\n\nmodel OrderItem {\n  id        Int     @id @default(autoincrement())\n  orderId   Int\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId Int\n  product   Product @relation(fields: [productId], references: [id], onDelete: Restrict)\n  quantity  Int\n  price     Decimal @db.Decimal(10, 2)\n\n  @@index([orderId])\n  @@index([productId])\n}\n\nmodel OrderRequest {\n  id           Int                @id @default(autoincrement())\n  sessionId    String\n  customerName String?\n  note         String?\n  status       OrderRequestStatus @default(PENDING)\n  items        OrderRequestItem[]\n  createdAt    DateTime           @default(now())\n  updatedAt    DateTime           @updatedAt\n\n  @@index([sessionId])\n  @@index([status])\n  @@index([createdAt])\n}\n\nmodel OrderRequestItem {\n  id             Int          @id @default(autoincrement())\n  orderRequestId Int\n  orderRequest   OrderRequest @relation(fields: [orderRequestId], references: [id], onDelete: Cascade)\n  productId      Int\n  product        Product      @relation(fields: [productId], references: [id], onDelete: Restrict)\n  productName    String\n  price          Decimal      @db.Decimal(10, 2)\n  quantity       Int\n\n  @@index([orderRequestId])\n  @@index([productId])\n}\n\nenum OrderRequestStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n}\n\nmodel ShopSettings {\n  id          String   @id @default(uuid())\n  logoUrl     String?  @map(\"logo_url\")\n  shopName    String   @map(\"shop_name\")\n  description String?\n  address     String?\n  phone       String?\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"shop_settings\")\n}\n",
